if(!UnityEditor.EditorApplication.isPlaying)throw new System.Exception("Runtime review requires play");
var camera=GameObject.Find("NPCReviewCamera")?.GetComponent<Camera>();if(camera==null){camera=new GameObject("NPCReviewCamera").AddComponent<Camera>();camera.CopyFrom(Camera.main);camera.tag="Untagged";camera.enabled=false;}
var npcs=UnityEngine.Object.FindObjectsByType<NPCController>(FindObjectsSortMode.None).Where(n=>n.transform.Find("StoryVisual")!=null).ToArray();
var npc=npcs.Single(n=>n.Data.npcId=="pawnshop");camera.transform.rotation=Quaternion.Euler(62,0,0);camera.transform.position=npc.transform.position+Vector3.up*.15f-camera.transform.forward*15f;camera.orthographic=true;camera.orthographicSize=3.6f;
var result=new{playing=UnityEditor.EditorApplication.isPlaying,paused=UnityEditor.EditorApplication.isPaused,timeScale=Time.timeScale,scenes=Enumerable.Range(0,UnityEngine.SceneManagement.SceneManager.sceneCount).Select(i=>UnityEngine.SceneManagement.SceneManager.GetSceneAt(i).name).ToArray(),npcs=npcs.Select(n=>new{id=n.Data.npcId,animator=n.GetComponentInChildren<Animator>().GetCurrentAnimatorStateInfo(0).normalizedTime,clip=n.GetComponentInChildren<Animator>().GetCurrentAnimatorClipInfo(0).Select(c=>c.clip.name).ToArray(),bounds=n.GetComponentInChildren<SkinnedMeshRenderer>().bounds.ToString("F3"),shader=n.GetComponentInChildren<SkinnedMeshRenderer>().sharedMaterial.shader.name,active=n.gameObject.activeInHierarchy}).ToArray()};
System.IO.File.WriteAllText("D:/Demo/ArtWork/StoryNPC62/UnityIntegration/RuntimeInitial.json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));
